#include <stdio.h>
#include <string.h>

#define MOD 1000000007

void ADD(int &a, int b) {
    a += b;
    a %= MOD;
}

int C[110][110], f[110][2][110][110];

int main() {
    int i, j, k, t, need, cnt, N, M, K, tak, now, then, ans;

    memset(C, 0, sizeof(C));
    for (i = 0; i <= 100; i++) {
        for (j = 0; j <= i; j++) {
            if (j == 0 || j == i)
                C[i][j] = 1;
            else
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
        }
    }

    while (scanf("%d%d%d", &N, &M, &K) == 3) {
        ans = 0;

        for (i = 0; i <= N; i++)
            for (j = 0; j <= 1; j++)
                for (k = 0; k <= K; k++)
                    for (t = 0; t <= N; t++)
                        f[i][j][k][t] = 0;

        for (j = 0; j <= M; j++) {
            now = j % 2;
            then = 1 - now;
            f[0][now][1][1] = 1;

            for (i = 1; i <= N; i++)
                for (cnt = 1; cnt <= K; cnt++)
                    ADD(ans, f[i][now][cnt][0]);

            for (i = 0; i <= N; i++) {
                for (cnt = 1; cnt <= K; cnt++) {
                    for (need = 1; need <= i + 1; need++) {
                        if (f[i][now][cnt][need] != 0) {
                            for (tak = need; tak + i <= N; tak++) {
                                int add = C[tak - 1][need - 1];
                                long long nextCnt = 1LL * cnt * add;

                                if (nextCnt <= K) {
                                    ADD(f[i + tak][then][(int)nextCnt]
                                         [i == 0 ? tak - need + 1 : tak - need],
                                        f[i][now][cnt][need]);
                                }
                            }
                            f[i][now][cnt][need] = 0;
                        }
                    }
                    f[i][now][cnt][0] = 0;
                }
            }
        }

        printf("%d\n", ans);
    }

    return 0;
}

